args<-commandArgs(TRUE);P<-normalizePath(args[1]);W<-file.path(P,'work/2026-10-29-awesome-map-replacements');S<-file.path(P,'biofigure')
suppressPackageStartupMessages({library(ggplot2);library(sf);library(dplyr);library(terra);library(patchwork)})
source(file.path(S,'scripts/figure_style.R'));set.seed(20261029)
wr<-function(x,p)jsonlite::write_json(x,p,auto_unbox=TRUE,pretty=TRUE,digits=NA)
finish<-function(mid,p,stem,q,width,height){w<-file.path(W,mid);saveRDS(p,file.path(w,'plot.rds'));q$stem<-stem;q$width_mm<-width;q$height_mm<-height;wr(q,file.path(w,'input-qc.json'));ggsave(file.path(w,'exploratory.png'),p,width=width,height=height,units='mm',dpi=180,device=ragg::agg_png,bg='white')}
z<-read.csv(file.path(W,'ASF-V03/NEON d15N data.csv'));stopifnot(nrow(z)==225,length(unique(z$plotID))==225,length(unique(z$siteID))==31,!anyNA(z[,c('Latitude','Longitude','soild15N','nlcdClass')]))
z$Ecosystem<-factor(tools::toTitleCase(z$nlcdClass),levels=c('Forest','Wetland','Grassland','Shrubland'));stopifnot(identical(as.numeric(table(z$Ecosystem)),c(118,25,53,29)))
write.csv(z,file.path(P,'results/plot_data/asf03_neon_plots_20261029.csv'),row.names=FALSE)
site<-z%>%group_by(siteID)%>%summarise(Longitude=mean(Longitude),Latitude=mean(Latitude),.groups='drop');site$labelX<-site$Longitude;site$labelY<-site$Latitude+.55
adjust<-data.frame(siteID=c('WREF','SOAP','SJER','ONAQ','RMNP','CPER','NIWO','CLBJ','UKFS','BLAN','SERC','MLBS','DELA','LENO','JERC','TALL','OSBS','GUAN','LAJA'),dx=c(-1.3,1.1,-1.5,1.4,1.7,1.8,-1.2,1,-1.4,-2.2,1.7,-1.6,-1.5,-1.5,1.8,1.8,1.4,.13,-.2),dy=c(.4,.2,-.5,.4,.4,.4,-.5,.5,.1,1.4,-.5,-.2,.5,-.7,-.4,.6,-.4,-.1,.15))
for(i in seq_len(nrow(adjust))){k<-match(adjust$siteID[i],site$siteID);site$labelX[k]<-site$Longitude[k]+adjust$dx[i];site$labelY[k]<-site$Latitude[k]+adjust$dy[i]}
site$labelX[site$siteID=='LAJA']<--67;site$labelX[site$siteID=='WREF']<--122.6;site$labelX[site$siteID=='GUAN']<--66.25;site$labelY[site$siteID=='GUAN']<-17.87;site$labelX[site$siteID=='NOGP']<--103;site$labelY[site$siteID=='NOGP']<-47.8;site$labelX[site$siteID=='DCFS']<--100;site$labelY[site$siteID=='DCFS']<-49;site$labelX[site$siteID=='RMNP']<--108;site$labelY[site$siteID=='RMNP']<-41.5;site$labelX[site$siteID=='CPER']<--103;site$labelY[site$siteID=='CPER']<-41.5;site$labelX[site$siteID=='WOOD']<--97;site$labelY[site$siteID=='WOOD']<-47.8;site$labelX[site$siteID=='TREE']<--90;site$labelY[site$siteID=='TREE']<-45.3;write.csv(site,file.path(P,'results/plot_data/asf03_neon_site_labels_20261029.csv'),row.names=FALSE)
states<-st_make_valid(st_read(file.path(P,'work/2026-10-29-maps-and-umap/sources/REPRO-058/data/us_shapefile/cb_2016_us_state_20m.shp'),quiet=TRUE));states<-st_transform(states,4326);sc<-st_coordinates(states);stopifnot(ncol(sc)==5);border<-data.frame(lon=sc[,1],lat=sc[,2],group=interaction(sc[,3],sc[,4],sc[,5],drop=TRUE))
w<-file.path(W,'ASF-V03');unzip(file.path(w,'wc2.1_10m_prec.zip'),exdir=file.path(w,'worldclim'));rf<-sort(list.files(file.path(w,'worldclim'),pattern='\\.tif$',full.names=TRUE));stopifnot(length(rf)==12);rain<-sum(terra::rast(rf),na.rm=FALSE);rain<-mask(crop(rain,vect(states)),vect(states));writeRaster(rain,file.path(P,'results/plot_data/asf03_worldclim_annual_precip_20261029.tif'),overwrite=TRUE);rd<-as.data.frame(rain,xy=TRUE,na.rm=FALSE);names(rd)<-c('lon','lat','MAP_mm');lev<-c('<200','200-400','400-600','600-800','800-1000','1000-1500','1500-2000','>=2000');rd$Rainfall<-cut(rd$MAP_mm,c(-Inf,200,400,600,800,1000,1500,2000,Inf),labels=lev,right=FALSE)
clim<-setNames(c('#4BA4D4','#7FBDE1','#B2D4E8','#DCEAF2','#E2BEDF','#B76FC4','#9426AF','#6841B3'),lev);eco<-c(Forest='#65B7B3',Wetland='#6B8057',Grassland='#EDAF65',Shrubland='#A45D55');shapes<-c(Forest=16,Wetland=15,Grassland=18,Shrubland=17)
th<-theme_bw(base_family='Arial',base_size=7)+theme(panel.grid=element_blank(),axis.text=element_text(size=7),axis.title=element_text(size=7),legend.text=element_text(size=7),legend.title=element_text(size=7),plot.margin=margin(2,2,2,2))
mapbase<-function(xlim,ylim,lab=TRUE){p<-ggplot()+geom_raster(data=rd,aes(lon,lat,fill=Rainfall))+scale_fill_manual(values=clim,drop=FALSE,na.value=NA,na.translate=FALSE,name='MAP (mm)',guide=guide_legend(nrow=1,title.position='left',keywidth=unit(4,'mm'),keyheight=unit(2,'mm')))+geom_path(data=border,aes(lon,lat,group=group),inherit.aes=FALSE,colour='#5E6970',linewidth=.13)+geom_point(data=z,aes(Longitude,Latitude,colour=Ecosystem,shape=Ecosystem),size=1.8,alpha=.8)+scale_colour_manual(values=eco,drop=FALSE,name=NULL)+scale_shape_manual(values=shapes,drop=FALSE,name=NULL)+coord_quickmap(xlim=xlim,ylim=ylim,expand=FALSE)+th+theme(legend.position='bottom',legend.box='vertical',legend.spacing.y=unit(1,'mm'));if(lab)p<-p+geom_text(data=site,aes(labelX,labelY,label=siteID),family='Arial',size=2.46,colour='#17232A');p}
main<-mapbase(c(-125,-66),c(24,50))+geom_segment(aes(x=-100,xend=-100,y=24,yend=50),colour='white',linewidth=.55)+geom_segment(aes(x=-98,xend=-98,y=24,yend=50),colour='white',linewidth=.55,linetype='dashed')+labs(x='Longitude',y='Latitude',tag='a')+guides(colour=guide_legend(order=1,nrow=1),shape=guide_legend(order=1,nrow=1),fill=guide_legend(order=2,nrow=2,byrow=TRUE,title.position='top',keywidth=unit(4,'mm'),keyheight=unit(2,'mm')))
ak<-mapbase(c(-170,-130),c(55,72))+scale_x_continuous(breaks=c(-160,-140),labels=function(x)paste0(abs(x),'W'))+scale_y_continuous(breaks=c(60,70),labels=function(x)paste0(x,'N'))+theme(legend.position='none',axis.title=element_blank(),axis.text=element_text(size=7),plot.margin=margin(0,0,0,0));pr<-mapbase(c(-67.5,-65.5),c(17.6,18.7))+scale_x_continuous(breaks=c(-67,-66),labels=function(x)paste0(abs(x),'W'))+scale_y_continuous(breaks=c(18,18.5),labels=function(x)paste0(x,'N'))+theme(legend.position='none',axis.title=element_blank(),axis.text=element_text(size=7),axis.text.y=element_blank(),axis.ticks.y=element_blank(),plot.margin=margin(0,0,0,0));main<-main+inset_element(ak,left=.02,bottom=.01,right=.31,top=.26,align_to='panel')+inset_element(pr,left=.78,bottom=.01,right=.995,top=.24,align_to='panel')
means<-z%>%group_by(Ecosystem)%>%summarise(soild15N=mean(soild15N),.groups='drop');means$Letters<-c('b','ab','a','a');means$labelY<-means$soild15N+1
box<-ggplot(z,aes(Ecosystem,soild15N,colour=Ecosystem))+geom_boxplot(width=.62,fill=NA,outlier.shape=NA,linewidth=.4)+geom_jitter(width=.16,height=0,size=1.2,alpha=.65)+geom_point(data=means,size=2.5,shape=21,fill=eco,colour='#313A3E',stroke=.35)+geom_text(data=means,aes(y=labelY,label=Letters),family='Arial',size=2.46,colour='#182127')+annotate('text',x=2.5,y=10.15,label='ANOVA P = 3.4e-6',family='Arial',size=2.46)+scale_colour_manual(values=eco,drop=FALSE)+coord_cartesian(ylim=c(-2.2,10.5),clip='off')+labs(x='Ecosystem',y='Soil delta15N')+th+theme(legend.position='none',axis.text.x=element_text(angle=45,hjust=1))
p<-wrap_plots(main,box+labs(tag='b'),widths=c(2.25,1))&theme(plot.tag=element_text(family='Arial',size=8,face='bold'))
a<-summary(aov(soild15N~Ecosystem,data=z))[[1]];pv<-a[1,'Pr(>F)'];stopifnot(abs(pv/3.4e-6-1)<.02)
finish('ASF-V03',p,'asf03_neon_ecosystems_20261029',list(data_origin='Author Figshare29311124 NEON d15N data.csv,225 unique biological plots,31 sites; original counts118/25/53/29 retained. All plot coordinates mapped,31 derived mean-coordinate site labels. WorldClim2.1 10-minute annual precipitation sum is a documented backdrop adaptation from source WorldClim v2; no simulated data.',crs='EPSG:4326',rows=225,sites=31,count_closure=TRUE,source_ANOVA_P='3.4e-6',independent_ANOVA_P=pv,statistical_scope='Existing source annotation retained; one-way ANOVA recomputed only as fixed-source consistency audit, not a new biological finding.',palette='Source-aligned eight-class blue-purple rainfall; four named source ecosystem colors',climate_source='https://geodata.ucdavis.edu/climate/worldclim/2_1/base/wc2.1_10m_prec.zip'),183,108)
