finish('ASF-V13',p,'asf13_pv_production_map_20261029',list(data_origin='Original author Data_Figures.RData12-region production_relative_2030_2022 and world_map; adapt Code_Figures.R Figure1c only. Retain author ratios and bins; these are published model outputs, not observed future production. No optimization or simulation rerun. Figure1a/b outside scope.',crs='EPSG:4326; coord_quickmap',regions=12,polygon_vertices=nrow(m),count_closure=TRUE,palette='Original author six-class YlGnBu palette and factor order'),183,104)
